edits.new:
/*  #177: the request debug dump's fixed reads stop at packet[33];
	    bytes from 34 are logged only while i < len.  The later field
	    dump, including packet[85], runs after packet = lp->data on the
	    307-byte reply.  Frames shorter than 278 bytes are rejected
	    before the memcpy of the request.  The len < 86 guard does not
	    protect a fixed request read of packet[85] (#560).  */

edits.old:
/*  #132: a full ARP/RARP body is 28 bytes, and everything below
	    (including the debug dump) reads up to packet[27], but the
	    caller only guarantees len >= 20. Reject shorter frames.  */

edits.new:
/*  The WRITE row is a CONTROL, not a proof of the `offset < 0'
	    guard: on the fseeko path a negative seek fails and the write is
	    refused anyway (diskimage.c:1256-1260 -> :1653-1657).  Only the
	    READ row above reds when the guard is dropped (a short read
	    returns 1, :1660).  On HACK_FSEEKO builds (:76-95) the write row
	    does red (#560).  */
	res = diskimage__internal_access(&d, 1, -4096, buf, 512);
	check("[CONTROL] WRITE at a NEGATIVE offset is refused", res, 0);
